// n8n Code node "Build request" (mode: Run Once for Each Item).
// Input: one transcribed Reel row from Supabase. Output: { id, body }, where body is
// the OpenRouter chat request that the "Summarise" HTTP node sends as-is.

// Tried in order; if one is down or rate-limited, OpenRouter moves to the next.
// openrouter/free picks any free model that's up, so the list can't go fully stale.
const MODELS = [
  'openai/gpt-oss-120b:free',
  'google/gemma-4-31b-it:free',
  'openrouter/free',
];

const CATEGORIES = [
  'AI & Tech',
  'Self-Help & Mindset',
  'Socialising & Relationships',
  'Health & Fitness',
  'Money & Career',
  'Other',
];

const SYSTEM = `You turn one short video (an Instagram Reel, TikTok or YouTube Short) into notes for a weekly self-improvement digest written in the style of Atomic Habits: practical, specific, no hype.

Reply with ONLY a JSON object, no markdown, in exactly this shape:
{
  "summary": "2-3 plain sentences: the video's main idea and why it matters. No 'In this video'.",
  "category": "one of: ${CATEGORIES.join(' | ')}",
  "action_steps": [
    {
      "step": "one concrete thing to do, as an instruction, max 12 words",
      "how": "exactly how to do it: when, where, or the words to say. 1-2 sentences.",
      "two_minute_version": "a version that takes under two minutes, to start the habit today"
    }
  ]
}

Rules:
- Use only what the video says. Never add facts, numbers, names or advice it doesn't contain.
- 1 to 3 action steps, best first. If the video has nothing anyone could act on (news, a joke), return an empty list.
- If the viewer left a note, it says what they care about: put that part first and build the steps around it.
- If there is no transcript, work from the caption only and keep the summary short. Don't guess what was said.
- Category guide: AI tools, apps, coding, tech news = "AI & Tech". Habits, discipline, motivation, mindset = "Self-Help & Mindset". Conversation, dating, friends, family = "Socialising & Relationships". Exercise, food, sleep = "Health & Fitness". Money, investing, jobs, skills for work = "Money & Career". Anything else = "Other".`;

const MAX_TRANSCRIPT_CHARS = 12000; // a long video still fits a free model's window

const reel = $json;
const transcript = (reel.transcript || '').slice(0, MAX_TRANSCRIPT_CHARS);
const user = [
  `Viewer's note: ${reel.note || '(none)'}`,
  `Caption: ${reel.caption || '(none)'}`,
  reel.has_speech && transcript
    ? `Transcript:\n${transcript}`
    : 'Transcript: (none: this video has no speech, only music and on-screen text)',
].join('\n\n');

return {
  json: {
    id: reel.id,
    body: {
      models: MODELS,
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: user },
      ],
      response_format: { type: 'json_object' },
      temperature: 0.3,
    },
  },
};

// n8n Code node "Read summary" (mode: Run Once for Each Item).
// Input: OpenRouter's reply. Output: the columns "Save summary" writes, with
// status 'done'. Throws on anything unusable, so the item goes down the error
// output to "Describe failure" and gets one retry.

const CATEGORIES = [
  'AI & Tech',
  'Self-Help & Mindset',
  'Socialising & Relationships',
  'Health & Fitness',
  'Money & Career',
  'Other',
];

const id = $('Build request').item.json.id;

// OpenRouter can answer 200 with an error inside (e.g. every model was busy)
if ($json.error) throw new Error(`OpenRouter: ${$json.error.message ?? JSON.stringify($json.error)}`);

const content = $json.choices?.[0]?.message?.content ?? '';
const model = $json.model ?? 'unknown model';

// Free models sometimes wrap the JSON in ```json fences or add a sentence around it
const start = content.indexOf('{');
const end = content.lastIndexOf('}');
if (start === -1 || end <= start) throw new Error(`${model} didn't return JSON: ${content.slice(0, 200)}`);

let data;
try {
  data = JSON.parse(content.slice(start, end + 1));
} catch (e) {
  throw new Error(`${model} returned broken JSON: ${e.message}`);
}

const summary = String(data.summary ?? '').trim();
if (!summary) throw new Error(`${model} returned no summary`);

// Match the category even if the model changed its case or spacing; anything else is Other
const wanted = String(data.category ?? '').toLowerCase().replace(/\s+/g, ' ').trim();
const category = CATEGORIES.find((c) => c.toLowerCase() === wanted) ?? 'Other';

const actionSteps = (Array.isArray(data.action_steps) ? data.action_steps : [])
  .filter((s) => s && String(s.step ?? '').trim())
  .slice(0, 3)
  .map((s) => ({
    step: String(s.step).trim(),
    how: String(s.how ?? '').trim(),
    two_minute_version: String(s.two_minute_version ?? '').trim(),
  }));

return {
  json: { id, summary, category, action_steps: actionSteps, status: 'done' },
};

// n8n Code node "Describe failure" (mode: Run Once for Each Item).
// Every failed step's error output ends here. It counts the attempt and gives up
// after one retry, which makes the Reel a Failed Reel for the Digest.

const MAX_ATTEMPTS = 2; // first try + one retry

const reel = $('Loop over reels').item.json;
const e = $json.error;
const message = e
  ? (typeof e === 'string' ? e : e.message ?? JSON.stringify(e))
  : `Can't read ${reel.platform} links yet`; // came from the Switch's fallback output

const attempts = (reel.retry_count ?? 0) + 1;
return {
  json: {
    id: reel.id,
    retry_count: attempts,
    status: attempts >= MAX_ATTEMPTS ? 'failed' : 'new',
    last_error: String(message).slice(0, 500),
  },
};
